import math

class Solution:
    def minSpeedOnTime(self, dist: list[int], hour: float) -> int:
        n = len(dist)
        if hour <= n - 1:
            return -1
        def can_arrive(speed: int) -> bool:
            time = 0.0
            for i in range(n - 1):
                time += math.ceil(dist[i] / speed)
            time += dist[-1] / speed
            return time <= hour
        lo, hi = 1, 10**7
        while lo < hi:
            mid = (lo + hi) // 2
            if can_arrive(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

